import React, { useEffect, useRef, useState } from 'react';
import { Text, View, Pressable, StyleSheet } from 'react-native';
import { tokens } from '../theme';
interface Reading { sensorId: string; value: number; unit: string; }
interface MeasurementCardProps { reading: Reading; onRefresh: () => void; }
const HIGHLIGHT_THRESHOLD = 38;
const styles = StyleSheet.create({ card: { padding: tokens.spacing.medium }, warning: { backgroundColor: tokens.colors.warningSurface } });
export function MeasurementCard({ reading, onRefresh }: MeasurementCardProps) {
  const [seconds, setSeconds] = useState(0);
  const timer = useRef<ReturnType<typeof setInterval> | undefined>(undefined);
  useEffect(() => {
    timer.current = setInterval(() => setSeconds(value => value + 1), 1000);
    return () => { if (timer.current !== undefined) clearInterval(timer.current); };
  }, []);
  const highlighted = reading.value >= HIGHLIGHT_THRESHOLD;
  return <View style={[styles.card, highlighted && styles.warning]}><Text>{reading.value}{reading.unit} · {seconds}s</Text><Pressable accessibilityRole="button" accessibilityLabel="刷新读数" onPress={onRefresh}><Text>刷新</Text></Pressable></View>;
}

