import React, { useEffect, useState } from 'react';
import { TextComposer } from './ui';
import { startRead, isCancelled, messageFor } from './services/attachmentReader';
interface Props { noteId: string; value: string; onChange: (value: string) => void; }
export function NoteEditor(props: Props) {
  const [draft, setDraft] = useState(props.value);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string>();
  useEffect(() => { setBusy(false); setError(undefined); }, [props.noteId]);
  async function readAttachment() {
    setBusy(true);
    setError(undefined);
    const task = startRead();
    try {
      const result = await task.result;
      setDraft(result.text);
      props.onChange(result.text);
    } catch (cause) {
      if (!isCancelled(cause)) setError(messageFor(cause));
    } finally { setBusy(false); }
  }
  return <TextComposer value={draft} onChangeText={setDraft} busy={busy} onReadAttachment={readAttachment} error={error} />;
}
